<script setup>
import { computed, ref, nextTick, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useDemo } from '../../stores/demo.js'
import { printReport } from '../../lib/exports.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import ReportFields from './visual/ReportFields.vue'
import FieldException from '../../components/FieldException.vue'
import StaticSection from '../../components/StaticSection.vue'
import {assessRequirements,incidentRequirements} from '../../data/reportingRequirements.js'
import {assessReport,reportReceiptRequirements,REPORT_REQUIREMENTS_VERSION} from './reportRequirements.js'
import {buildMAICSections} from '../data/reportLogic.js'
import { clone, today, display, officeOptions, investigatorOptions } from './common.js'
import { maicGroups, initialFields, initializeFields } from './maic.js'
const route=useRoute(),store=useDemo(),draft=ref(null),error=ref(''),success=ref(''),stage=ref('1B'),validationStatus=ref('review'),receiptDialog=ref(false),receiptDate=ref(''),receiptSource=ref(''),receiptError=ref('')
const event=computed(()=>store.getEvent(route.params.id))
const reports=computed(()=>store.visibleRecords('reports').filter(r=>r.eventId===event.value?.id && ['1B','2','3B'].includes(r.type)).sort((a,b)=>String(b.createdAt || b.date).localeCompare(String(a.createdAt || a.date)) || b.revision-a.revision))
const groups=computed(()=>maicGroups.filter(g=>g.stages.includes(draft.value?.type) && (!g.compatibility || g.fields.some(f=>draft.value?.fields?.[f.key]?.length))))
const editable=computed(()=>draft.value && draft.value.status!=='issued' && store.can('investigate',event.value))
const stageGuide=computed(()=>({'1B':{title:'Initial report',message:'Record what is known now: occurrence, involved vessels, reported consequences and initial actions. Unknown facts can remain blank.'},'2':{title:'Progress update',message:'Record what changed since the last report and the information as-of date. Keep earlier revisions for reference.'},'3B':{title:'Final investigation report',message:'Use the factual record and evidence to document findings, analysis, conclusions and recommendations. Complete the applicable findings and record any unavailable information beside the field.'}}[draft.value?.type||stage.value]))
const essentialOccurrenceKeys=['occurrenceDate','occurrenceTime','place','occurrenceNarrative','informationSources']
const isOccurrence=g=>g.fields.some(f=>f.key==='occurrenceNarrative')
const groupId=g=>'report-section-'+g.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')
const groupLabel=g=>g.title.replace(/^Final report · /,'').replace(/ \(Form 3B pp?[0-9–-]+\)/,'')
async function showSection(key){const group=groups.value.find(g=>g.fields.some(f=>f.key===key));if(!group)return;await nextTick();document.getElementById(groupId(group))?.scrollIntoView({behavior:'smooth',block:'start'})}
const reportAssessment=computed(()=>assessReport({...draft.value,status:draft.value?.status==='issued'?'issued':validationStatus.value},event.value))
watch(()=>[draft.value?.fields,draft.value?.receivedDate],()=>{if(!draft.value||draft.value.status==='issued')return;for(const item of assessReport(draft.value,event.value).items)if(!item.missing)delete draft.value.reportingExceptions?.[item.key];if(draft.value.receivedDate)delete draft.value.reportingExceptions?.receivedDate},{deep:true})
const receiptAssessment=computed(()=>assessRequirements(reportReceiptRequirements(draft.value||{}),draft.value?.reportingExceptions))
function openReceipt(){receiptDate.value=draft.value?.receivedDate||'';receiptSource.value=draft.value?.receiptMetadata?.sourceRef||'';receiptError.value='';receiptDialog.value=true}
function recordReceipt(){try{const record=store.recordReportReceipt(draft.value.id,{receivedDate:receiptDate.value,sourceRef:receiptSource.value});draft.value.receivedDate=record.receivedDate;draft.value.receiptMetadata=clone(record.receiptMetadata);receiptDialog.value=false;success.value='Report receipt recorded; report content and sign-off are retained.'}catch(error){receiptError.value=error.message}}
const requiredKeys=computed(()=>reportAssessment.value.items.map(item=>item.field).filter(Boolean))
function scrollToRequirement(item){const element=[...document.querySelectorAll('[data-requirement-key]')].find(element=>element.dataset.requirementKey===item?.key);element?.scrollIntoView({behavior:'smooth',block:'center'})}
const evidence=computed(()=>store.visibleRecords('evidence').filter(e=>e.eventId===event.value?.id))
function load(r){draft.value=clone(r);draft.value.fields=initializeFields(draft.value.fields || {});if(!draft.value.fields.occurrenceNarrative && draft.value.fields.narrative)draft.value.fields.occurrenceNarrative=draft.value.fields.narrative;draft.value.evidenceIds ||= [];draft.value.reportingExceptions ||= {};validationStatus.value=draft.value.status==='review'||draft.value.status==='issued'?'issued':'review';for(const group of maicGroups)for(const f of group.fields){if(f.type==='checks' && draft.value.fields[f.key]===undefined)draft.value.fields[f.key]=[]}error.value='';success.value=''}
watch(()=>[route.params.id,route.query.reportId],()=>{const requested=reports.value.find(r=>r.id===route.query.reportId);if(requested)load(requested);else draft.value=null},{immediate:true})
function create(type,base){const revisions=reports.value.filter(r=>r.type===type);load({eventId:event.value.id,type,revision:Math.max(0,...revisions.map(r=>r.revision || 0))+1,status:'draft',date:today(),asOf:today(),receivedDate:'',officeId:store.currentUser.value?.officeId||'',preparedBy:store.currentUser.value?.name || '',designation:'Marine casualty investigator',notedBy:'',notedDate:'',reportingExceptions:clone(base?.reportingExceptions||{}),sourceReportingExceptions:clone(base?.sourceReportingExceptions??event.value.reportingExceptions??{}),sourceReportingLabels:clone(base?.sourceReportingLabels||Object.fromEntries(incidentRequirements(event.value,{stage:'review'}).map(item=>[item.key,item.label]))),fields:base ? clone(base.fields) : initialFields(event.value),evidenceIds:base ? [...(base.evidenceIds || [])] : [...(event.value.evidenceIds || [])]})}
async function save(status='draft'){
 try{error.value='';success.value='';if(!store.can('investigate',event.value))throw Error('Investigation permission required.');if(draft.value.status==='issued')throw Error('Issued revisions are retained. Create a new revision to make changes.');if(status==='issued' && draft.value.status!=='review')throw Error('Save this revision for review before issuing.');if(status!=='draft'){validationStatus.value=status;const assessment=assessReport({...draft.value,status},event.value);if(!assessment.ready){await nextTick();scrollToRequirement(assessment.unresolved[0]);throw Error(`${assessment.unresolved[0].label} is required. Enter it or explain an allowed Unknown / Not Applicable beside the field (${assessment.unresolved.length} item(s) remaining).`)}}
 const data=clone(draft.value);data.status=status;if(!Object.hasOwn(data,'sourceReportingExceptions')){data.sourceReportingExceptions=clone(event.value.reportingExceptions||{});data.sourceReportingLabels=Object.fromEntries(incidentRequirements(event.value,{stage:'review'}).map(item=>[item.key,item.label]))}if(status!=='draft')data.requirementsVersion=REPORT_REQUIREMENTS_VERSION;data.createdBy ||= store.currentUser.value?.id;data.createdAt ||= new Date().toISOString();data.updatedAt=new Date().toISOString();if(status==='review'){data.reviewedBy=store.currentUser.value?.id;data.reviewedAt=new Date().toISOString()}if(status==='issued'){data.issuedBy=store.currentUser.value?.id;data.issuedAt=new Date().toISOString()}for(const g of groups.value)for(const f of g.fields)if(f.type==='number'){const v=data.fields[f.key];data.fields[f.key]=v==='' || v===undefined || v===null ? null : Number(v);if(data.fields[f.key]!==null && (!Number.isInteger(data.fields[f.key]) || data.fields[f.key]<0))throw Error(`${f.label} must be a whole non-negative number or unknown.`)}
 const result=data.id ? store.update('reports',data.id,data) : store.recordReport(data);load(result);success.value=`MAIC ${result.type} revision ${result.revision} saved as ${status}.`;
 }catch(e){error.value=e.message}
}
function fieldText(f){const value=draft.value.fields[f.key];return Array.isArray(value) ? (value.map(v=>f.options?.find(o=>typeof o==='object' && o.value===v)?.label || v).join(', ') || 'Not recorded') : display(value)}
function preview(){if(!draft.value)return;const report=draft.value;printReport({title:`MAIC Form ${report.type} · ${event.value.ref}`,subtitle:`Revision ${report.revision} · ${report.status} · Demonstration / fictional data`,metadata:{reportDate:report.date,asOf:report.asOf,signature:'No actual signature — demonstration only'},sections:buildMAICSections({type:report.type,event:event.value,report,evidence:evidence.value.filter(item=>report.evidenceIds.includes(item.id))})})}
function assign(id){try{store.saveEvent({...event.value,investigatorId:id});error.value=''}catch(e){error.value=e.message}}
</script>
<template><div class="page-wrap"><template v-if="event"><PageHeader title="Investigation workbench" :subtitle="`${event.ref} · ${event.type} · ${event.place || 'Location unknown'}`"><template #actions><q-btn flat no-caps label="Incident workspace" :to="`/admin/incidents/${event.id}`"/></template></PageHeader>
 <q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" rounded>{{error}}</q-banner><q-banner v-if="success" class="bg-green-1 text-positive q-mb-md" rounded>{{success}}</q-banner>
 <div class="panel q-mb-md"><div class="report-start-heading"><div><div class="section-title q-mb-xs">1. Choose a report stage</div><p class="muted q-mb-none">Continue a saved revision, or create the next report.</p></div><q-select style="min-width:250px" outlined dense clearable :model-value="event.investigatorId" @update:model-value="assign" :options="investigatorOptions(store)" emit-value map-options label="Investigator"/></div><div class="toolbar-row q-mt-md q-mb-none"><q-select v-model="stage" :options="[{label:'Form 1B · Initial',value:'1B'},{label:'Form 2 · Progress',value:'2'},{label:'Form 3B · Final',value:'3B'}]" emit-value map-options outlined dense style="min-width:230px" label="New report stage"/><q-btn color="primary" no-caps icon="add" label="Create draft" @click="create(stage)"/><q-space/><q-btn flat no-caps label="Cases" :to="{path:'/admin/cases',query:{eventId:event.id}}"/><q-btn flat no-caps label="Follow-up" :to="{path:'/admin/actions',query:{eventId:event.id}}"/></div></div>
 <div class="workbench-grid"><aside class="panel"><StaticSection class="revision-disclosure" :label="`Saved revisions (${reports.length}) and sources`" header-class="text-weight-bold"><div class="section-title">Retained revisions</div><p class="muted">Choose a draft to continue, or open an issued revision to read it.</p><q-list separator><q-item v-for="r in reports" :key="r.id" clickable @click="load(r)" :active="draft?.id===r.id" active-class="text-primary"><q-item-section><q-item-label>Form {{r.type}} · revision {{r.revision}}</q-item-label><q-item-label caption>{{r.asOf || r.date}} · {{r.preparedBy || 'Preparer pending'}}</q-item-label><StatusBadge class="q-mt-xs" :status="r.status"/></q-item-section></q-item></q-list><p v-if="!reports.length" class="muted">Create the first initial report draft.</p><q-separator class="q-my-md"/><div class="section-title">Source evidence</div><div v-for="e in evidence" :key="e.id" class="q-mb-sm"><q-icon name="description" class="q-mr-xs"/>{{e.name}}<div class="muted">{{e.sourceRef || 'Reference not supplied'}}</div></div><q-btn flat no-caps label="Manage evidence" :to="{path:'/admin/documents',query:{eventId:event.id}}"/></StaticSection></aside>
 <section class="panel report-editor" v-if="draft"><div class="toolbar-row"><div><div class="section-title">MAIC Form {{draft.type}} · revision {{draft.revision}}</div><StatusBadge :status="draft.status"/></div><q-space/><q-btn outline no-caps icon="print" label="Preview / print" @click="preview"/><q-btn v-if="draft.id&&store.can('investigate',event)" flat no-caps icon="mark_email_read" label="Record receipt" @click="openReceipt"/><q-btn v-if="draft.id" flat no-caps label="New revision" @click="create(draft.type,draft)"/></div><q-banner v-if="draft.status==='issued'" rounded class="q-mt-md bg-blue-1 text-primary">Issued revisions are retained. Use New revision to record a subsequent progress update or amendment.</q-banner><section class="stage-guidance q-mt-lg"><div class="text-weight-bold">2. Complete the {{stageGuide.title.toLowerCase()}}</div><p class="muted q-mt-xs q-mb-sm">{{stageGuide.message}}</p><div class="row q-gutter-xs"><q-btn v-if="draft.type!=='2'" flat dense no-caps color="primary" label="Occurrence" @click="showSection('occurrenceNarrative')"/><q-btn v-if="draft.type==='2'" flat dense no-caps color="primary" label="Progress update" @click="showSection('progressSummary')"/><q-btn flat dense no-caps color="primary" label="Consequences" @click="showSection('fatalities')"/><q-btn v-if="draft.type==='3B'" flat dense no-caps color="primary" label="Causes and findings" @click="showSection('machineryFailures')"/><q-btn v-if="draft.type==='3B'" flat dense no-caps color="primary" label="Analysis" @click="showSection('analysis')"/><q-btn flat dense no-caps color="primary" label="Recommendations" @click="showSection('recommendations')"/></div></section><q-form @submit="save('draft')" class="q-mt-lg"><fieldset :disabled="!editable" class="report-fieldset"><h3 class="section-title" id="report-header">Report dates and sign-off</h3><div class="form-grid">
 <section data-requirement-key="officeId"><q-select v-model="draft.officeId" outlined :options="officeOptions(store)" emit-value map-options label="Submitting MARINA Office *"/><FieldException :assessment="reportAssessment" :exceptions="draft.reportingExceptions" field-key="officeId" :readonly="!editable"/></section>
 <section data-requirement-key="receivedDate"><q-input :model-value="draft.receivedDate||'Not recorded'" outlined readonly label="Date Received by MARINA — receipt metadata"/><FieldException :assessment="receiptAssessment" :exceptions="draft.reportingExceptions" field-key="receivedDate" :readonly="!editable"/><p class="text-caption muted q-mt-xs">For the receipt summary only. Use Record receipt when received, including after issue.</p></section>
 <section v-for="header in [{key:'date',label:'Report date',type:'date'},{key:'asOf',label:'Information as of',type:'date'},{key:'preparedBy',label:'Prepared by',type:'text'},{key:'designation',label:'Designation',type:'text'},{key:'notedBy',label:'Noted by / director',type:'text'},{key:'notedDate',label:'Noted date',type:'date'}]" :key="header.key" :data-requirement-key="header.key"><q-input v-model="draft[header.key]" outlined :type="header.type" :stack-label="header.type==='date'" :label="header.label+(reportAssessment.items.some(item=>item.key===header.key)?' *':'')"/><FieldException :assessment="reportAssessment" :exceptions="draft.reportingExceptions" :field-key="header.key" :readonly="!editable"/></section>
 </div><section class="q-mt-md" data-requirement-key="sourceDocuments"><q-select v-model="draft.evidenceIds" multiple use-chips outlined :options="evidence.map(e=>({label:e.name,value:e.id}))" emit-value map-options label="Linked source / vessel documents *"/><FieldException :assessment="reportAssessment" :exceptions="draft.reportingExceptions" field-key="sourceDocuments" :readonly="!editable"/></section>
 <q-banner v-if="draft.type==='3B'" rounded class="q-mt-md bg-blue-1 text-primary">Select only findings supported by evidence. An unchecked box means no finding recorded. Leave unknown crew/passenger allocations blank.</q-banner>
 <StaticSection v-for="g in groups" :key="`${draft.type}-${draft.id||'new'}-${g.title}`" :id="groupId(g)" :label="groupLabel(g)" header-class="text-weight-bold" class="report-section q-mt-md"><div class="q-pa-sm"><template v-if="isOccurrence(g)"><ReportFields :definitions="g.fields.filter(f=>essentialOccurrenceKeys.includes(f.key))" :values="draft.fields" :editable="editable" :required-keys="requiredKeys" :assessment="reportAssessment" :exceptions="draft.reportingExceptions"/><StaticSection label="Classification, position and office details" icon="tune" class="q-mt-md"><ReportFields class="q-pa-sm" :definitions="g.fields.filter(f=>!essentialOccurrenceKeys.includes(f.key))" :values="draft.fields" :editable="editable" :required-keys="requiredKeys" :assessment="reportAssessment" :exceptions="draft.reportingExceptions"/></StaticSection></template><ReportFields v-else :definitions="g.fields" :values="draft.fields" :editable="editable" :required-keys="requiredKeys" :assessment="reportAssessment" :exceptions="draft.reportingExceptions"/></div></StaticSection></fieldset><p class="text-caption muted q-mt-sm">Fields marked * need a recorded value, assessment evidence, or an allowed Unknown / Not Applicable explanation beside that field. Drafts and retained issued reports remain available.</p>
 <p class="muted text-caption q-mt-md">Saving this report preserves its own revision. Correct event totals in the incident workspace when required; progress reports do not add new casualty totals.</p><div class="report-save-actions" v-if="editable"><div class="text-weight-bold">3. Save, review and issue</div><div class="toolbar-row q-mt-sm q-mb-none"><q-btn color="primary" no-caps type="submit" label="Save draft"/><q-btn outline no-caps label="Save for review" @click="save('review')"/><q-btn v-if="draft.status==='review'" color="positive" no-caps label="Issue demonstration revision" @click="save('issued')"/></div><p class="text-caption muted q-mt-sm q-mb-none">Save a draft at any time. Issuing requires a saved review state and completed sign-off details.</p></div></q-form></section>
 <section class="panel" v-else><q-icon name="fact_check" size="44px" color="primary"/><h2 class="text-h6">Choose a report revision</h2><p class="muted">Create a draft to prepare initial findings, a repeatable progress update or the final investigation report.</p><q-btn color="primary" no-caps label="Create initial report" @click="create('1B')"/></section></div></template><section v-else class="panel"><h2>Investigation unavailable</h2><p>The incident does not exist or is outside your scope.</p><q-btn to="/admin/investigations" label="Back to investigations" no-caps color="primary"/></section><q-dialog v-model="receiptDialog"><q-card style="width:560px;max-width:94vw"><q-card-section><h3 class="section-title">Record Receipt by MARINA</h3><p class="muted">Record the actual receipt date and its supporting reference. This updates receipt metadata while retaining the issued content, revision and sign-off.</p><q-banner v-if="receiptError" class="bg-red-1 text-negative q-mb-md">{{receiptError}}</q-banner><q-input v-model="receiptDate" outlined type="date" stack-label label="Date Received by MARINA *"/><q-input v-model="receiptSource" outlined label="Receipt Source / Reference *" class="q-mt-md"/></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn color="primary" no-caps label="Save receipt" @click="recordReceipt"/></q-card-actions></q-card></q-dialog></div></template>
<style scoped>.form-grid>section{min-width:0}.report-start-heading{display:flex;justify-content:space-between;gap:20px;align-items:center}.stage-guidance{background:var(--ss-soft,#f1f5f9);border:1px solid var(--ss-border,#e2e5ea);border-radius:10px;padding:16px}.report-section{border:1px solid var(--ss-border,#e2e5ea);border-radius:10px;scroll-margin-top:100px}.report-save-actions{position:sticky;bottom:12px;background:var(--ss-card,#fff);border:1px solid var(--ss-border,#e2e5ea);border-radius:10px;padding:16px;margin-top:22px;box-shadow:0 4px 15px #12303b0b;z-index:2}.report-editor{min-width:0}.workbench-grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:20px;align-items:start}.report-fieldset{border:0;margin:0;padding:0;min-width:0}@media(max-width:1000px){.workbench-grid{grid-template-columns:1fr}.report-start-heading{align-items:flex-start;flex-direction:column}}@media(max-width:600px){.report-save-actions{position:static}.report-start-heading .q-field{min-width:0!important;width:100%}}</style>
